  "6-1": {
   "list.c": "#include <stdio.h>\n#include <stdlib.h>\n#include \"list.h\"\n\nstatic list_node_t* insert_node(list_node_t *p, int val);\nstatic void remove_node(list_node_t *p);\n\nlist_node_t* create_node(int val)\n/* 値 val を保持する新しい節点を作成し, その節点へのポインタを返す */\n{\n  list_node_t *new_node;\n  new_node = malloc(sizeof(list_node_t));\n  if (new_node == NULL) {\n    fprintf(stderr, \"節点の割当てに失敗しました\\n\");\n    exit(1);\n  }\n  new_node->val = val;\n  new_node->next = NULL;\n  return new_node;\n}\n\nstatic list_node_t* insert_node(list_node_t *n, int val)\n/* n の指す節点の直後に, 値 val を保持する新しい節点を挿入し,\n   その節点へのポインタを返す */\n{\n  list_node_t *new_node = create_node(val);\n  new_node->next = n->next;   /* 新しい節点の次 = n の次だった節点 */\n  n->next = new_node;         /* n の次 = 新しい節点 */\n  return new_node;\n}\n\nvoid list_print(list_node_t *head_p)\n/* リストの内容を表示する */\n{\n  list_node_t *p;\n  printf(\"[\");\n  for (p = head_p->next; p != NULL; p = p->next) {   /* ダミーの次から */\n    printf(\" %d\", p->val);\n  }\n  printf(\" ]\\n\");\n}\n\nstatic void remove_node(list_node_t *p)\n/* p の指す節点の *直後* の節点を削除 */\n{\n  list_node_t *old = p->next;\n  if (old==NULL) {\n    fprintf(stderr, \"Error: p->next = NULL\\n\");\n    exit(1);\n  }\n  p->next = old->next;\n  free(old);\n  old = NULL;\n}\n\nlist_node_t* list_insert(list_node_t* head_p, int val)\n/* ヘッダが head_p のリストの先頭に値 val (の節点) を挿入する */\n{\n  list_node_t* p = insert_node(head_p,val);\n  return p;\n}\n\nlist_node_t* list_find(list_node_t *head_p, int val)\n/* リスト中に値が val の節点を探す\n   見つかればその節点のポインタを, なければ NULL を返す */\n{\n  list_node_t *p;\n  for (p = head_p->next; p != NULL; p = p->next) {\n    if (p->val == val) {\n      return p;\n    }\n  }\n  return NULL;\n}\n\nlist_node_t* list_insert_uniq(list_node_t* head_p, int val)\n/* 同じ値がなければ先頭に挿入. あればその節点を返す */\n{\n  list_node_t *p = list_find(head_p, val);\n  if (p != NULL) {\n    return p;\n  }\n  return list_insert(head_p, val);\n}\n\nlist_node_t* list_insert_delete_dup(list_node_t* head_p, int val)\n/* 同じ値がなければ先頭に挿入. あればその節点を削除して NULL を返す */\n{\n  list_node_t *q = list_find(head_p, val);\n  list_node_t *p;\n  if (q == NULL) {\n    return list_insert(head_p, val);\n  }\n  for (p = head_p; p->next != q; p = p->next) {   /* q の直前の節点 p を探す */\n  }\n  remove_node(p);\n  return NULL;\n}\n\nlist_node_t* list_insert_delete_dup2(list_node_t* head_p, int val)\n/* list_find を使わず, 1 回の走査で list_insert_delete_dup と同じ動作 */\n{\n  list_node_t *p;\n  for (p = head_p; p->next != NULL; p = p->next) {   /* 先読み: p->next を調べる */\n    if (p->next->val == val) {\n      remove_node(p);\n      return NULL;\n    }\n  }\n  return insert_node(head_p, val);\n}\n\nlist_node_t* list_sorted_insert_uniq(list_node_t* head_p, int val)\n/* 同じ値がなければ, 昇順を保つ位置に挿入 */\n{\n  list_node_t *p = list_find(head_p, val);\n  if (p != NULL) {\n    return p;\n  }\n  for (p = head_p; p->next != NULL && p->next->val < val; p = p->next) {\n  }\n  return insert_node(p, val);\n}\n\nlist_node_t* list_sorted_insert_uniq2(list_node_t* head_p, int val)\n/* list_find を使わず, 1 回の走査で list_sorted_insert_uniq と同じ動作 */\n{\n  list_node_t *p;\n  for (p = head_p; p->next != NULL && p->next->val < val; p = p->next) {\n  }\n  if (p->next != NULL && p->next->val == val) {\n    return p->next;\n  }\n  return insert_node(p, val);\n}\n\nlist_node_t* list_sorted_find(list_node_t* head_p, int val)\n/* 昇順のリストで val を探す. val より大きい値に出会ったら打ち切る */\n{\n  list_node_t *p;\n  for (p = head_p->next; p != NULL && p->val <= val; p = p->next) {\n    if (p->val == val) {\n      return p;\n    }\n  }\n  return NULL;\n}\n\nvoid list_delete(list_node_t* head_p)\n{\n  list_node_t *p = head_p->next;\n  while ( p!=NULL ) {\n    list_node_t *next = p->next;\n    free(p);\n    p = next;\n  }\n  head_p->next = NULL;\n}\n"
  },
