   "list8time.c": "#include <stdio.h>\n#include <stdlib.h>\n#include <time.h>\n#include \"list.h\"\n#include \"myrand.h\"\n\nint main(void)\n{\n  list_node_t *head_p = create_node(0); /* ヘッダ (ダミー) */\n  clock_t clk_start, clk_end;\n  int n, i, found;\n\n  fprintf(stderr, \"n = \");\n  if (scanf(\"%d\", &n) != 1 || n <= 0) {      /* (0) 正整数 n */\n    fprintf(stderr, \"正整数を入力してください\\n\");\n    return 1;\n  }\n\n  /* (1) n 個の乱数を list_insert_uniq で挿入 */\n  myrand_init();\n  clk_start = clock();\n  for (i=0; i<n; i++) {\n    list_sorted_insert_uniq2(head_p, myrand());\n  }\n  clk_end = clock();\n  printf(\"(1) sorted_ins2 : cpu = %g [sec]\\n\", (double) (clk_end-clk_start)/CLOCKS_PER_SEC);\n\n  /* (2) 同じ乱数を list_find で検索 (必ず見つかる) */\n  myrand_init();\n  found = 0;\n  clk_start = clock();\n  for (i=0; i<n; i++) {\n    if (list_sorted_find(head_p, myrand()) != NULL) { found++; }\n  }\n  clk_end = clock();\n  printf(\"(2) sfind (hit) : cpu = %g [sec]  found = %d\\n\", (double) (clk_end-clk_start)/CLOCKS_PER_SEC, found);\n\n  /* (3) 異なる乱数を list_find で検索 (myrand_init を呼ばずに続ける) */\n  found = 0;\n  clk_start = clock();\n  for (i=0; i<n; i++) {\n    if (list_sorted_find(head_p, myrand()) != NULL) { found++; }\n  }\n  clk_end = clock();\n  printf(\"(3) sfind (miss): cpu = %g [sec]  found = %d\\n\", (double) (clk_end-clk_start)/CLOCKS_PER_SEC, found);\n\n  list_delete(head_p);\n  free(head_p);\n  return 0;\n}\n"
