  "6-9": {
   "tree.c": "#include <stdio.h>\n#include <stdlib.h>\n#include <assert.h>\n#include \"tree.h\"\nstatic tree_node_t* create_node(int val);\n\nstatic tree_node_t* create_node(int val)\n/* 値 val を保持する新しい節点を作成し, その節点へのポインタを返す */\n{\n  tree_node_t *new_node;\n  new_node = malloc(sizeof(tree_node_t));\n  if (new_node == NULL) {\n    fprintf(stderr, \"節点の割当てに失敗しました\\n\");\n    exit(1);\n  }\n  new_node->data = val;\n  new_node->left = NULL;\n  new_node->right = NULL;\n  return new_node;\n}\n\ntree_node_t* tree_insert_uniq(tree_node_t *n, int val)\n/* n を根とする二分木に val (の節点) を挿入する */\n{\n  if (n==NULL) {\n    n = create_node(val);\n  }\n  else if (val < n->data) {\n    n->left = tree_insert_uniq(n->left, val);\n  }\n  else if (val > n->data) {\n    n->right = tree_insert_uniq(n->right, val);\n  }\n  /* val == n->data のときは何もしない (同じ値は挿入しない) */\n  return n;\n}\n\nvoid tree_print(tree_node_t *n)\n/* 二分木の内容を表示する */\n{\n  if (n!=NULL) {\n    tree_print(n->left);          /* 小さい値 (左の部分木) を先に */\n    printf(\" %d\", n->data);       /* 自分 */\n    tree_print(n->right);         /* 大きい値 (右の部分木) を後に */\n  }\n}\n\ntree_node_t* tree_find(tree_node_t *n, int val)\n/* *n を根とする二分木中に値が val の節点を探す\n   見つかればその節点のポインタを, なければ NULL を返す */\n{\n  while (n != NULL) {\n    if (val == n->data) {\n      return n;\n    }\n    else if (val < n->data) {\n      n = n->left;      /* 小さければ左へ */\n    }\n    else {\n      n = n->right;     /* 大きければ右へ */\n    }\n  }\n  return NULL;\n}\n\nvoid tree_delete(tree_node_t *n)\n/* 二分木のデータを解放する */\n{\n  if (n!=NULL) {\n    tree_delete(n->left);\n    tree_delete(n->right);\n    free(n);\n  }\n}\n"
  },
